def load_ignore_file(path):
    pats = []
    try:
        with open(path, 'r', errors='ignore') as f:
            for line in f:
                line=line.strip()
                if line=="" or line.startswith('#') or line.startswith('!'):
                    continue
                pats.append(line)
    except:
        pass
    return pats

def match_ignore(pattern, name, path):
    # ag ignore: supports glob (*, ?, **) and literal names?
    # Simplify: use fnmatch for basename and full path, plus literal directory match
    # pattern may contain / ? For now, match basename with fnmatch, and also full rel path
    # Also handle trailing / for dirs?
    pat = pattern.strip()
    if pat == "":
        return False
    # remove trailing /?
    if pat.endswith('/'):
        pat = pat[:-1]
    # if pattern contains /, match against path, else basename
    if '/' in pat:
        # match full path with fnmatch
        # Use fnmatch.fnmatch for path
        if fnmatch.fnmatch(path, pat) or fnmatch.fnmatch(path, "*/"+pat):
            return True
        # also try basename?
        if fnmatch.fnmatch(os.path.basename(path), os.path.basename(pat)):
            return True
        return False
    else:
        # match basename
        if fnmatch.fnmatch(name, pat):
            return True
        # literal?
        if name == pat:
            return True
        return False

